const phone='2348026676582';
document.querySelector('#year').textContent=new Date().getFullYear();
const date=document.querySelector('#date');const today=new Date();date.min=[today.getFullYear(),String(today.getMonth()+1).padStart(2,'0'),String(today.getDate()).padStart(2,'0')].join('-');
document.querySelector('#booking-form').addEventListener('submit',event=>{event.preventDefault();const data=new FormData(event.currentTarget);let message=`Hi 23 Lux Nails! My name is ${data.get('name').trim()}. I'd like to enquire about ${data.get('service')}.`;if(data.get('date'))message+=`\nPreferred date: ${data.get('date')}.`;if(data.get('notes').trim())message+=`\n${data.get('notes').trim()}`;message+='\nPlease let me know your prices and availability.';window.open(`https://wa.me/${phone}?text=${encodeURIComponent(message)}`,'_blank','noopener');});
const modal=document.querySelector('#lightbox');document.querySelectorAll('.gallery-item').forEach(item=>item.addEventListener('click',()=>{const img=item.querySelector('img');document.querySelector('#lightbox-image').src=img.src;document.querySelector('#lightbox-image').alt=img.alt;document.querySelector('#lightbox-caption').textContent=item.dataset.label;document.querySelector('#look-book').dataset.look=item.dataset.label;modal.showModal();}));document.querySelector('#close-lightbox').onclick=()=>modal.close();modal.addEventListener('click',event=>{if(event.target===modal)modal.close();});document.querySelector('#look-book').onclick=event=>{document.querySelector('#notes').value=`I'm interested in the look: ${event.currentTarget.dataset.look}.`;modal.close();};
if('IntersectionObserver' in window){const observer=new IntersectionObserver(entries=>entries.forEach(entry=>{if(entry.isIntersecting){entry.target.classList.add('visible');observer.unobserve(entry.target);}}),{threshold:.08});document.querySelectorAll('.section-heading,.service-list>a,.booking>div').forEach(el=>{el.classList.add('reveal');observer.observe(el);});}